// Vérifier que les deux produits sont présents dans le panier.
cy.get('.cart_item').should('have.length', 2);
// Retirer le Sauce Labs Backpack du panier.
cy.get('[data-test="remove-sauce-labs-backpack"]').click();
// Vérifier que le Backpack a disparu et que le badge est passé à un.
cy.contains('[data-test="inventory-item-name"]', 'Sauce Labs Backpack').should('not.exist');
// Vérifier que le Bike Light reste dans le panier.
cy.contains('[data-test="inventory-item-name"]', 'Sauce Labs Bike Light').should('be.visible');
// Vérifier que le badge du panier indique un produit restant.
cy.get('[data-test="shopping-cart-badge"]').should('be.visible').and('have.text', '1');
// Retirer le Sauce Labs Bike Light du panier.
cy.get('[data-test="remove-sauce-labs-bike-light"]').click();
// Vérifier que le Bike Light a disparu du panier.
cy.contains('[data-test="inventory-item-name"]', 'Sauce Labs Bike Light').should('not.exist');
// Vérifier que la liste des articles est maintenant vide.
cy.get('.cart_item').should('not.exist');
// Vérifier que le badge disparaît lorsque le panier est vide.
cy.get('[data-test="shopping-cart-badge"]').should('not.exist');
